export const body = "<div class=\"source-table\"><table><tbody><tr><td><p><strong>The GPU Pipeline</strong></p></td></tr><tr><td><div class=\"source-table\"><table><tbody><tr><td><p><strong>Introduction</strong></p>\n<p>Now that you understand how different components in a console manipulate data to draw frames, we can look into the GPU pipeline. This pipeline describes how the GPU receives and processes data to output graphics.</p>\n<p>There are four general steps in the pipeline:</p>\n<ol><li><strong>Loading a mesh</strong></li><li><strong>Grouping vertices into triangles</strong></li><li><strong>Converting triangles to pixels</strong></li><li><strong>Giving each pixel a color</strong></li></ol></td><td><p><a class=\"source-figure\" href=\"assets/library-inline/1e964e6e57f53e525bb6.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/1e964e6e57f53e525bb6.webp\" width=\"538\" height=\"598\" style=\"--source-width:269px\" alt=\"Illustration 1\" loading=\"lazy\" decoding=\"async\"></a></p></td></tr><tr><td><p><a class=\"source-figure\" href=\"assets/library-inline/c7758a049eeed2640ba9.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/c7758a049eeed2640ba9.webp\" width=\"565\" height=\"598\" style=\"--source-width:276px\" alt=\"Illustration 2\" loading=\"lazy\" decoding=\"async\"></a></p></td><td><p><strong>Index &amp; vertex buffer </strong></p>\n<p>A 3D mesh is loaded into the game engine in two pieces:</p>\n<ul><li><strong>Vertex Buffer</strong>: contains vertices and their properties (position, UV, normal, color, etc.)</li><li><strong>Index Buffer</strong>: lists vertices that are connected to form triangles</li></ul>\n<p>Together, these two pieces form triangles and locate them in the game world.</p></td></tr><tr><td><p><strong>Depth-stencil buffer</strong></p>\n<p>A depth-stencil buffer is a texture resource containing depth data and stencil data.</p>\n<ul><li><strong>Depth data </strong>determines the distance of each pixel</li><li><strong>Stencil data </strong>masks the pixels that can be updated</li></ul>\n<p>Together, these two types of data decide whether a pixel will appear on screen or not.</p></td><td><p><a class=\"source-figure\" href=\"assets/library-inline/57d706c97221d52956a3.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/57d706c97221d52956a3.webp\" width=\"508\" height=\"598\" style=\"--source-width:269px\" alt=\"Illustration 3\" loading=\"lazy\" decoding=\"async\"></a></p></td></tr><tr><td><p><a class=\"source-figure\" href=\"assets/library-inline/3dec3bb2c3f104c2c902.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/3dec3bb2c3f104c2c902.webp\" width=\"609\" height=\"521\" style=\"--source-width:276px\" alt=\"Illustration 4\" loading=\"lazy\" decoding=\"async\"></a></p></td><td><p><strong>Blending</strong></p>\n<p>Blending  is the process of combining one or more pixel values to render the final color.</p></td></tr><tr><td><p><strong>The rendering process</strong></p>\n<ul><li><strong>Input assembly</strong>: the GPU reads vertex and index buffers from memory</li><li><strong>Vertex shading</strong>: the vertex shader determines the on-screen position of each vertex of the mesh</li><li><strong>Rasterization</strong>: scans the triangles into pixels</li><li><strong>Pixel shading</strong>: the pixel shader gives each rasterized pixel a color based on the data in the draw call</li><li><strong>Render Target output</strong>: the render target runs some tests (depth, alpha, stencil, etc.) then outputs the pixel in the memory (RAM)</li></ul></td><td><p><a class=\"source-figure\" href=\"assets/library-inline/05ba728dc51a9382d434.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/05ba728dc51a9382d434.webp\" width=\"617\" height=\"563\" style=\"--source-width:269px\" alt=\"Illustration 5\" loading=\"lazy\" decoding=\"async\"></a></p></td></tr><tr><td colspan=\"2\"><p><strong>EXAMPLE –  </strong><strong>The rendering process</strong></p>\n<p><a class=\"source-figure\" href=\"assets/library-inline/5735bb1fe49cd5d032a7.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/5735bb1fe49cd5d032a7.webp\" width=\"932\" height=\"470\" style=\"--source-width:276px\" alt=\"Illustration 6\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p><a class=\"source-figure\" href=\"assets/library-inline/c125313a68e23a1634b5.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/c125313a68e23a1634b5.webp\" width=\"700\" height=\"394\" style=\"--source-width:276px\" alt=\"Illustration 7\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p><a class=\"source-figure\" href=\"assets/library-inline/f2c838871bd6e831aa12.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/f2c838871bd6e831aa12.webp\" width=\"932\" height=\"470\" style=\"--source-width:276px\" alt=\"Illustration 8\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p><a class=\"source-figure\" href=\"assets/library-inline/cc2c42f26d663a303064.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/cc2c42f26d663a303064.webp\" width=\"926\" height=\"467\" style=\"--source-width:276px\" alt=\"Illustration 9\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p><a class=\"source-figure\" href=\"assets/library-inline/e84a664511f35858ba5b.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/e84a664511f35858ba5b.webp\" width=\"926\" height=\"467\" style=\"--source-width:276px\" alt=\"Illustration 10\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p><a class=\"source-figure\" href=\"assets/library-inline/595952e9a4b988ed2ea8.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/595952e9a4b988ed2ea8.webp\" width=\"926\" height=\"467\" style=\"--source-width:276px\" alt=\"Illustration 11\" loading=\"lazy\" decoding=\"async\"></a></p>\n<p><a class=\"source-figure\" href=\"assets/library-inline/43318c5ac03b46fa6a4f.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/43318c5ac03b46fa6a4f.webp\" width=\"926\" height=\"467\" style=\"--source-width:276px\" alt=\"Illustration 12\" loading=\"lazy\" decoding=\"async\"></a></p></td></tr></tbody></table></div></td></tr></tbody></table></div>";
